query:
UPDATE candidates 
SET primary_status = 'won', primary_called_at = NOW()
WHERE state = 'NM' AND office = 'Senate' AND party = 'Democrat' AND name LIKE '%Luján%';

UPDATE races
SET dem_nominee = 'Ben Ray Luján', status = 'general_set_dem'
WHERE state = 'NM' AND office = 'Senate' AND year = 2026;
